AE_stage_background=Class(object)function AE_stage_background:init()	--	background.init(self,false)	--resource	LoadImageFromFile('AE_stage_a','AE_stage_a.png')	LoadImageFromFile('AE_stage_b','AE_stage_b.png')	LoadImageFromFile('AE_stage_c','AE_stage_c.png')	LoadImageFromFile('AE_stage_d','AE_stage_d.png')	LoadImageFromFile('AE_stage_e','AE_stage_e.png')	--set 3d camera and fog	Set3D('eye',0,6.8,-10.)	Set3D('at',0,-1.2,-4.9)	Set3D('up',0,1,0)	Set3D('z',2,23.5)	Set3D('fovy',0.7)	Set3D('fog',6.0,22.7,Color(200,50,0,170))	--	self.speed=0.02	self._z=0	self.eyxx=0	self.eyxy=0endfunction AE_stage_background:frame()	task.Do(self)	self._z=self._z+self.speed	if self.timer%15==0 and self.timer>5 then		for i=1,ran:Int(2,7) do			local size=ran:Float(0.25,1)			local x=ran:Float(-220,220)			local y=ran:Float(224,230)			local color=Color(125+125*(size-1),255,255,255)--  		New(AE_stage_leaf,x,y,size,color)		end	endendfunction AE_stage_background:render()	RenderClear(lstg.view3d.fog[3])	SetViewMode'3d'	for j=-2,10 do		local dz=4*j-math.mod(self._z,4)		Render4V('AE_stage_a',0,0,dz+2,-4,0,dz+2,-4,0,dz-2,0,0,dz-2)		Render4V('AE_stage_a',0,0,dz+2.5,4,0,dz+2.5,4,0,dz-1.5,0,0,dz-1.5)	end	for j=-2,10 do		local dz=4*j-math.mod(self._z,4)		local Dx=0.2		Render4V('AE_stage_b',-2.5,1,dz+2,-0.5,1,dz+2,-0.5,1,dz-2,-2.5,1,dz-2)		Render4V('AE_stage_b',2.5-Dx,1,dz+2,0.5-Dx,1,dz+2,0.5-Dx,1,dz-2,2.5-Dx,1,dz-2)	end	for j=-2,10 do		local dz=4*j-math.mod(self._z,4)		local Dx=-0.2		Render4V('AE_stage_c',-2.5-Dx,1.5,dz+1.5,-0.5-Dx,1.5,dz+1.5,-0.5-Dx,1.5,dz-2.5,-2.5-Dx,1.5,dz-2.5)		Render4V('AE_stage_c',2.5+Dx,1.5,dz+2,0.5+Dx,1.5,dz+1,0.5+Dx,1.5,dz-2,2.5+Dx,1.5,dz-2)	end	SetImageState('AE_stage_d','',Color(205+50*sin(self.timer),255,255,255))	for j=-2,10 do		local dz=4*j-math.mod(self._z,4)		Render4V('AE_stage_d',-2.5,2,dz+2,-0.5,2,dz+2,-0.5,2,dz-2,-2.5,2,dz-2)		Render4V('AE_stage_d',2.5,2,dz+2,0.5,2,dz+1,0.5,2,dz-2,2.5,2,dz-2)	end	SetImageState('AE_stage_d','',Color(255,255,255,255))	for j=-2,10 do		local dz=4*j-math.mod(self._z,4)		Render4V('AE_stage_d',-3,2.6,dz+2,-1,2.6,dz+2,-1,2.6,dz-2,-3,2.6,dz-2)		Render4V('AE_stage_d',3,2.6,dz+1.5,1,2.6,dz+1.5,1,2.6,dz-2.5,3,2.6,dz-2.5)	end	SetViewMode'world'endAE_stage_leaf=Class(object)function AE_stage_leaf:init(x,y,size,color)	self.x=x	self.y=y	self.img='AE_stage_e'	self.size=size	self.hscale=size	self.vscale=size	self.group=GROUP_GHOST	self.omiga=ran:Float(-3,-2)	self.layer=LAYER_BG-1	self.color=color	self.vx=ran:Float(-1,1)	self.bound=false	self.vy=ran:Float(-5.5,-4)endfunction AE_stage_leaf:frame()	task.Do(self)	self.hscale=self.hscale+self.size/100	self.vscale=self.vscale+self.size/100	if self.y<-230 then Del(self) endendfunction AE_stage_leaf:render()	SetImageState(self.img,"",self.color)	SetViewMode"world"	object.render(self)	SetImageState(self.img,"",Color(255,255,255,255))end